// 466 - Allowed host/domain code points (1)
TYPED_TEST(URIWhatwgTest, AllowedHostDomainCodePoints1) {
    static constexpr auto details = R"JSON-URL({
    "input": "http://!\"$&'()*+,-.;=_`{}~/",
    "base": null,
    "href": "http://!\"$&'()*+,-.;=_`{}~/",
    "origin": "http://!\"$&'()*+,-.;=_`{}~",
    "protocol": "http:",
    "username": "",
    "password": "",
    "host": "!\"$&'()*+,-.;=_`{}~",
    "hostname": "!\"$&'()*+,-.;=_`{}~",
    "port": "",
    "pathname": "/",
    "search": "",
    "hash": ""
})JSON-URL";
    auto const            ctx =
      this->template parse_from_string<TypeParam>(stl::string_view{R"URL(http://!"$&'()*+,-.;=_`{}~/)URL", 27});
    EXPECT_TRUE(uri::is_valid(ctx.status)) << to_string(uri::get_value(ctx.status)) << details;
    if (!uri::is_valid(ctx.status)) {
        return;
    }

    EXPECT_EQ(uri::scheme(ctx.out), "http") << details;
    EXPECT_EQ(uri::username(ctx.out), "") << details;
    EXPECT_EQ(uri::password(ctx.out), "") << details;
    EXPECT_EQ(uri::hostname(ctx.out), "!\"$&'()*+,-.;=_`{}~") << details;
    EXPECT_EQ(uri::port(ctx.out), "") << details;
    EXPECT_EQ(uri::render_path(ctx), "/") << details;
    EXPECT_EQ(uri::render_queries(ctx), "") << details;
    EXPECT_EQ(uri::fragment(ctx.out), "") << details;
    EXPECT_EQ(uri::href(ctx), R"URL(http://!"$&'()*+,-.;=_`{}~/)URL") << details;
}

